{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket is not configured to block public ACLs, potentially allowing public access to the bucket's objects."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket lacks a Public Access block, which could lead to unintended public exposure of the bucket."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, making it difficult to track and monitor access to the bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"flowbucket\" {\n  bucket        = \"${local.resource_prefix.value}-flowlogs\"\n  force_destroy = true\n  tags = merge({\n    Name        = \"${local.resource_prefix.value}-flowlogs\"\n    Environment = local.resource_prefix.value\n    }, {\n  })\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"flowbucket\" {\n  bucket = aws_s3_bucket.flowbucket.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_logging\" \"flowbucket\" {\n  bucket = aws_s3_bucket.flowbucket.id\n\n  target_bucket = \"${local.resource_prefix.value}-flowlogs-access-logs\"\n  target_prefix = \"/\"\n}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to block public ACLs and policies, and aws_s3_bucket_logging to enable access logging for the S3 bucket."
}
